B.lp=new A.mR(0,"somali")
B.avr=new A.c8("\ud83d\udc2a","Beri hore, geel yar oo la yiraahdo Geli wuxuu ku noolaa dhul qallalan.","Long ago, a young camel named Geli lived on dry land.","\u0641\u064a \u0642\u062f\u064a\u0645 \u0627\u0644\u0632\u0645\u0627\u0646\u060c \u0639\u0627\u0634 \u062c\u0645\u0644 \u0635\u063a\u064a\u0631 \u0627\u0633\u0645\u0647 \u062c\u0644\u064a \u0641\u064a \u0623\u0631\u0636 \u062c\u0627\u0641\u0629.")
B.avB=new A.c8("\u2600\ufe0f","Maalin maalmaha ka mid ah, qorraxdu waxay u dhalaashay sida dahab.","One day, the sun shone like gold.","\u0641\u064a \u064a\u0648\u0645 \u0645\u0646 \u0627\u0644\u0623\u064a\u0627\u0645\u060c \u0623\u0634\u0631\u0642\u062a \u0627\u0644\u0634\u0645\u0633 \u0643\u0627\u0644\u0630\u0647\u0628.")
B.avL=new A.c8("\ud83c\udf0a","Geli wuxuu maqlay in baddu ay tahay meel cajiib ah \u2014 wuxuu goostay inuu arko!","Geli heard the sea was wonderful \u2014 he decided to see it!","\u0633\u0645\u0639 \u062c\u0644\u064a \u0623\u0646 \u0627\u0644\u0628\u062d\u0631 \u0645\u0643\u0627\u0646 \u0631\u0627\u0626\u0639 \u2014 \u0642\u0631\u0631 \u0623\u0646 \u064a\u0631\u0627\u0647!")
B.avG=new A.c8("\ud83c\udfd6\ufe0f",'Markuu yimid xeebta, wuxuu arkay cir buluug ah iyo hirar cadcad. "Waa qurux!" ayuu yiri.','At the beach he saw blue sky and white waves. "So beautiful!" he said.','\u0639\u0646\u062f \u0627\u0644\u0634\u0627\u0637\u0626 \u0631\u0623\u0649 \u0633\u0645\u0627\u0621 \u0632\u0631\u0642\u0627\u0621 \u0648\u0623\u0645\u0648\u0627\u062c\u0627\u064b \u0628\u064a\u0636\u0627\u0621. \u0642\u0627\u0644: "\u0645\u0627 \u0623\u062c\u0645\u0644\u0647\u0627!"')
B.avx=new A.c8("\u2b50","Geli wuxuu bartay in safarku uu baro wax cusub \u2014 sidaad adna u baran karto maalin kasta!","Geli learned that travel teaches new things \u2014 just like you can every day!","\u062a\u0639\u0644\u0645 \u062c\u0644\u064a \u0623\u0646 \u0627\u0644\u0633\u0641\u0631 \u064a\u0639\u0644\u0651\u0645 \u0623\u0634\u064a\u0627\u0621 \u062c\u062f\u064a\u062f\u0629 \u2014 \u0645\u062b\u0644\u0643 \u0643\u0644 \u064a\u0648\u0645!")
